/* Source: src/kernel/scrollbars.css */
/*
 * v7 固定全局无滚动条外观内核。
 * 只隐藏浏览器滚动条外观，不修改 overflow、touch-action、pointer-events，
 * 不隐藏滚动容器、跳转键、功能按钮或 input[type="range"]。
 * 全局 * 是本项目唯一允许的无边界选择器例外，不得增加其他声明。
 */
::-webkit-scrollbar {
    display: none !important;
}

* {
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}

/* Source: src/tokens.css */
:root {
  --td-paper: #fffafd;
  --td-backdrop: #eee7ff;
  --td-pink: #ffe3f2;
  --td-blue: #e1f3ff;
  --td-ink: #3f137c;
  --td-muted: #7653b0;
  --td-line: #ab8de5;
  --td-focus: #702bbc;
  --td-disabled: #ece3f5;
  --td-body-font: "Songti SC", "SimSun", "Noto Serif CJK SC", serif;
  --td-ui-font: "Microsoft YaHei", "PingFang SC", sans-serif;
  --td-avatar-width: min(240px, 42cqi);
  --td-avatar-height: calc(var(--td-avatar-width) * .75);
  --st-theme-mobile-reading-width: 100%;
  --st-theme-mobile-reading-padding: 12px;
  --topBarIconSize: 24px;
  --topBarBlockSize: 52px;
  --bottomFormIconSize: 24px;
  --bottomFormBlockSize: 40px;
}
@media (max-width: 700px) {
  :root {
    --td-avatar-width: min(144px, 42cqi);
    --td-avatar-height: calc(var(--td-avatar-width) * .85);
    --topBarIconSize: 21px;
    --topBarBlockSize: 46px;
    --bottomFormIconSize: 23px;
    --bottomFormBlockSize: 36px;
  }
}

:root { --td-no-effect: none; --td-empty: ""; --td-check-size: .65em; --td-check-shape: polygon(14% 44%, 0 65%, 50% 100%, 100% 16%, 80% 0%, 43% 62%); --td-check-off: scale(0); --td-check-on: scale(1); }

:root { --td-wing: max(0px, calc((min(1040px, 96cqi) - var(--td-avatar-width)) / 2)); }

:root { --td-scroll-x: auto; }

