/* Source: src/chat-layout.css */
/* Full theme 0.2.0: real image plus separate pointer-transparent ornament. */
#chat {
  background: transparent;
  color: var(--td-ink);
  text-shadow: none;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  gap: 12px;
  padding: 12px 8px;
  min-height: 0;
  max-height: none;
  flex: 1 1 0;
}
#chat .mes[is_system="false"] {
  flex-direction: column;
  align-items: stretch;
  flex-shrink: 0;
  container-type: inline-size;
  inline-size: 100%;
  min-inline-size: 0;
  box-sizing: border-box;
  margin: 0;
  padding: 18px 22px 16px;
  border: 2px solid var(--td-line);
  border-radius: 5px;
  background: var(--td-paper);
  color: var(--td-ink);
  text-shadow: none;
  box-shadow: none;
}
#chat .mes[is_system="false"] > .mesAvatarWrapper {
  align-self: center;
  inline-size: 100%;
  min-inline-size: 0;
  margin-inline: auto;
  padding: calc(var(--td-avatar-height) * .38) 0 calc(var(--td-avatar-height) * .55);
  box-sizing: border-box;
  text-align: center;
}
#chat .mes[is_system="false"] > .mesAvatarWrapper > .avatar {
  inline-size: var(--td-avatar-width);
  block-size: var(--td-avatar-height);
  max-inline-size: 100%;
  margin-inline: auto;
  padding: 0;
  position: relative;
  box-sizing: border-box;
  border: 2px solid var(--td-line);
  border-radius: 12px;
  background: var(--td-blue);
  opacity: 1;
  flex: none;
}
#chat .mes[is_user="true"][is_system="false"] > .mesAvatarWrapper > .avatar {
  background: var(--td-pink);
}
#chat .mes[is_system="false"] > .mesAvatarWrapper > .avatar > img {
  inline-size: 100%;
  block-size: 100%;
  max-inline-size: 100%;
  object-fit: cover;
  border: 1px solid var(--td-line);
  border-radius: 6px;
  box-shadow: none;
  box-sizing: border-box;
}
#chat .mes[is_system="false"] > .mes_block {
  inline-size: 100%;
  min-inline-size: 0;
  padding-inline: 0;
  box-sizing: border-box;
}
#chat .mes[is_system="false"] > .mes_block > .ch_name {
  flex-direction: column;
  align-items: stretch;
  gap: 4px;
}
#chat .mes[is_system="false"] > .mes_block > .ch_name > .flex1 {
  justify-content: center;
  min-inline-size: 0;
  inline-size: 100%;
}
#chat .mes[is_system="false"] > .mes_block > .ch_name > .flex1 > .alignItemsBaseline {
  justify-content: center;
  align-items: center;
  flex-direction: column;
  min-inline-size: 0;
  max-inline-size: 100%;
  gap: 4px;
}
#chat .mes[is_system="false"] .name_text {
  color: var(--td-ink);
  font-family: var(--td-body-font);
  font-size: 1.25em;
  overflow-wrap: anywhere;
  text-align: center;
}
#chat .mes[is_system="false"] .timestamp {
  color: var(--td-muted);
  font-family: var(--td-ui-font);
  font-size: .8em;
  font-weight: 400;
}
#chat .mes[is_system="false"] > .mes_block > .mes_text {
  inline-size: 100%;
  max-inline-size: 100%;
  min-inline-size: 0;
  margin-inline: auto !important;
  padding: 12px 14px 4px;
  box-sizing: border-box;
}
#chat .mes[is_system="false"] :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
  color: var(--td-muted);
  font-size: .75em;
  text-shadow: none;
}
@media (max-width: 700px) {
  #chat { padding: 8px 6px; gap: 10px; }
  #chat .mes[is_system="false"] {
    padding: 12px 8px;
    flex-direction: column;
    align-items: stretch;
  }
  #chat .mes[is_system="false"] > .mesAvatarWrapper {
    padding-block: calc(var(--td-avatar-height) * .38) calc(var(--td-avatar-height) * .55);
    align-self: center;
    margin-inline: auto;
  }
  #chat .mes[is_system="false"] > .mes_block {
    inline-size: 100%;
    min-inline-size: 0;
  }
  #chat .mes[is_system="false"] > .mes_block > .mes_text {
    inline-size: min(100%, var(--st-theme-mobile-reading-width));
    max-inline-size: 100%;
    margin-inline: auto !important;
    padding-inline: var(--st-theme-mobile-reading-padding) !important;
    box-sizing: border-box;
  }
}

#chat .mes[is_system="false"] > .mesAvatarWrapper > .avatar::after {
 content: ""; position: absolute; pointer-events: none; box-sizing: border-box;
 inline-size: calc(var(--td-avatar-width) + var(--td-wing) * 2); block-size: calc(var(--td-avatar-height) * 1.672);
 inset-inline-start: calc(var(--td-wing) * -1); top: calc(var(--td-avatar-height) * -.296);
 border-style: solid; border-color: transparent; border-width: calc(var(--td-avatar-height) * .296) var(--td-wing) calc(var(--td-avatar-height) * .376);
 border-image-source: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/1aa34fd8b3fe1478e6cef0531496989d2a291403/assets/%E7%B3%96%E6%A2%A6%E4%B9%8B%E9%97%B4/user-frame.png"); border-image-slice: 128 827 163 826 fill; border-image-repeat: stretch;
}
#chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper > .avatar::after {
 block-size: calc(var(--td-avatar-height) * 2.028); top: calc(var(--td-avatar-height) * -.515); border-width: calc(var(--td-avatar-height) * .515) var(--td-wing) calc(var(--td-avatar-height) * .513); border-image-source: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/1aa34fd8b3fe1478e6cef0531496989d2a291403/assets/%E7%B3%96%E6%A2%A6%E4%B9%8B%E9%97%B4/character-frame.png"); border-image-slice: 184 751 183 750 fill;
}
#chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper { padding-block: calc(var(--td-avatar-height) * .6) calc(var(--td-avatar-height) * .58); }

